/* Fullscreen — selector toàn cục (overlay nằm ngoài .page-content) */
.sed-dash-fullscreen {
    position: fixed;
    inset: 0;
    z-index: 3000;
    background: #f1f5f9;
    display: flex;
    flex-direction: column;
}

.sed-dash-fullscreen.d-none {
    display: none !important;
}

.sed-dash-fullscreen-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1.25rem;
    background: #fff;
    border-bottom: 1px solid #e2e8f0;
    box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06);
}

.sed-dash-fullscreen-body {
    flex: 1;
    padding: 1rem 1.25rem;
    min-height: 0;
    overflow: hidden;
}

.sed-dash-fullscreen-chart-wrap {
    width: 100%;
    height: 100%;
    background: #fff;
    border-radius: 12px;
    border: 1px solid #e2e8f0;
    padding: 0.75rem;
}

.sed-dash-fullscreen-chart-wrap > div {
    width: 100%;
    height: 100%;
}

.sed-dash-fullscreen-horizontal .sed-dash-fullscreen-body,
.sed-dash-fullscreen-vertical .sed-dash-fullscreen-body {
    overflow-y: auto;
    overflow-x: hidden;
}

.sed-dash-fullscreen-horizontal .sed-dash-fullscreen-chart-wrap,
.sed-dash-fullscreen-vertical .sed-dash-fullscreen-chart-wrap {
    overflow: auto;
    min-height: calc(100vh - 88px);
}

.sed-dash-fullscreen-line .sed-dash-fullscreen-body {
    overflow: hidden;
}

.sed-dash-fullscreen-line .sed-dash-fullscreen-chart-wrap {
    overflow: hidden;
    min-height: calc(100vh - 88px);
}

.sed-dash-fullscreen-center .sed-dash-fullscreen-body {
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.sed-dash-fullscreen-center .sed-dash-fullscreen-chart-wrap {
    min-height: auto;
    max-width: 720px;
    margin: 0 auto;
    height: auto;
}

@media (max-width: 767.98px) {
    .sed-dash-fullscreen-body {
        padding: 0.5rem;
    }
}

function getEl(id) {
    return document.getElementById(id);
}

function getFullscreenChartHeight(preferredHeight, minHeight) {
    var viewportHeight = window.innerHeight || 800;
    var floorHeight = minHeight || 420;
    var targetHeight = preferredHeight || floorHeight;
    return Math.max(viewportHeight - 110, targetHeight, floorHeight);
}

function ensureFullscreenOverlay() {
    var overlay = getEl("sedDashFullscreenOverlay");
    if (overlay && overlay.parentNode !== document.body) {
        document.body.appendChild(overlay);
    }
}

